'use strict';
window.PrepWorkflow=(()=>{
  const model=window.PrepJourneyModel;
  let service=null,serviceWorkspace=null,serviceLoading=false,aiBusy=false,aiError='',aiEpoch=0;
  const symbol=(name)=>({learn:'↗',practice:'⌘',studio:'◉',progress:'↗'}[name]||'→');
  const profile=()=>state.learningJourney?.version===1?model.profile(state.learningJourney):null;
  const key=p=>JSON.stringify([p.role,p.domain,p.language,p.company,p.level]);
  function score(result){const parts=[...result.milestones.map(s=>({id:s.id,label:s.short,earned:s.total?s.done/s.total:0,detail:`${s.done} of ${s.total} steps recorded`})),{id:'mock',label:'Full mock reflection',earned:result.mockComplete?1:0,detail:result.mockComplete?'Five-round self-assessment recorded':'Five-round self-assessment pending'}];const value=Math.min(result.ready?100:99,Math.floor(parts.reduce((sum,p)=>sum+p.earned,0)/parts.length*100));return {value,parts,provisional:!result.historyKnown||!!result.missing.length||!result.gradingAvailable};}
  function scorePanel(p,result,compact=false){const s=score(result);return `<section class="workflow-score ${compact?'is-compact':''}" aria-label="Interview readiness evidence score"><div class="workflow-score-top"><span class="workflow-eyebrow">INTERVIEW READINESS</span><span class="workflow-status">${s.provisional?'Evidence incomplete':result.ready?'Path checkpoints met':'Building evidence'}</span></div><div class="workflow-score-value"><strong>${s.value}<small>/100</small></strong><div><h3>${result.ready?'Your preparation checkpoints are met.':'Every step needs evidence.'}</h3><p>${s.provisional?'This provisional score will refresh when the missing evidence is available.':'Your selected path’s evidence coverage. It is not a probability of passing an interview.'}</p></div></div><details class="workflow-score-details"><summary>How is this score calculated?</summary><p>Six equally weighted areas: five learning stages and your full mock reflection. Each stage earns its share from recorded steps. Reviews and rehearsals are self-assessed; Java coding requires current full contract checks. Independent coding requires no recorded assistance. Missing material stays in the denominator. 100 requires every readiness checkpoint.</p>${s.parts.map(part=>`<div class="workflow-score-row"><span>${esc(part.label)}<small>${esc(part.detail)}</small></span><progress value="${part.earned}" max="1" aria-label="${esc(part.label)} evidence coverage"></progress></div>`).join('')}<p>AI suggestions and company preferences never award points. The score is a study aid, not a validated assessment of interview ability. <a href="#/progress">Inspect all evidence</a></p></details></section>`;}
  function home(){const p=window.PrepPilotUI.workspaceReady?.()?profile():null,r=p?window.PrepJourney.snapshot(p):null;return `<div class="workflow-home"><section class="workflow-hero"><div class="workflow-hero-copy"><span class="workflow-eyebrow"><i></i> YOUR NEXT ROLE STARTS WITH A CLEARER PATH</span><h1>Prepare with purpose.<br><em>Interview with<br>confidence.</em></h1><p>One connected preparation journey. Learn what matters, solve realistic problems and rehearse with an AI interviewer—built around the role you want.</p><div class="workflow-actions"><a class="button primary large" href="${p?'#/learn':'#/learn?setup=1'}">${p?'Continue my preparation':'Build my preparation track'} <span aria-hidden="true">↗</span></a><a class="workflow-text-link" href="#/studio">Explore Interview Studio →</a></div><div class="workflow-assurances"><span>✓ Free to start</span><span>✓ Your work stays yours</span><span>✓ Answers when you choose</span></div></div><div class="workflow-preview"><div class="workflow-preview-top"><span class="workflow-live-dot"></span>${p?'YOUR PREPARATION TRACK':'A PATH BUILT AROUND YOU'}<span>PREPSPACE</span></div><div class="workflow-preview-person"><span class="workflow-person-icon" aria-hidden="true">↗</span><div><small>${p?'YOUR TARGET ROLE':'START WITH YOUR GOAL'}</small><h2>${p?esc(roleConfig.find(x=>x.id===p.role)?.name):'Where do you want to go?'}</h2><p>${p?esc([p.company||'Your next company',p.domain,languageConfig[p.language].name].join(' · ')):'Your role. Your domain. Your language. Your company.'}</p></div></div><ol class="workflow-preview-stages">${[['01','Learn the essentials','Clear explanations, examples and checks.'],['02','Put it into practice','Real scenarios. Hints when you need them.'],['03','Meet your AI interviewer','A conversation with relevant follow-ups.'],['04','Know your next step','An explainable score, backed by your work.']].map(([n,title,desc])=>`<li><span>${n}</span><div><strong>${title}</strong><small>${desc}</small></div><span aria-hidden="true">${n==='04'?'↗':'✓'}</span></li>`).join('')}</ol><div class="workflow-preview-footer">${p?`${r.done} of ${r.total} preparation steps recorded`:'From “where do I start?” to “I can explain this.”'}<span aria-hidden="true">→</span></div></div></section><section class="workflow-proof"><span>REALISTIC WORK</span><p>Banking Java & SDET specialism</p><span>COMPLETE PREPARATION</span><p>Five interview rounds</p><span>PROGRESS WITH CONTEXT</span><p>Assisted and independent work</p></section>${p?`<section class="workflow-return"><div><span class="workflow-eyebrow">WELCOME BACK</span><h2>Your next step is waiting.</h2><p>${esc(r.currentName)} · ${r.done} of ${r.total} steps recorded</p></div><a class="button primary" href="#/learn">Open my track →</a></section>`:''}<section class="workflow-section"><div class="workflow-section-heading"><span class="workflow-eyebrow">LESS GUESSWORK. MORE MEANINGFUL PRACTICE.</span><h2>Preparation that connects the dots.</h2><p>Build understanding, prove it in code and bring it into the conversation.</p></div><div class="workflow-feature-grid">${[['01','Learn','Make the difficult feel approachable.','Work through a Java data-structures tutorial with verified examples, output reveals and short recall checks.','#/learning?language=java','Explore Learn'],['02','Practice','Build skills you can use at work.','Solve banking scenarios, debug broken code and design tests. Contracts, examples and failure details make expectations clear.','#/lab?round=coding','Explore Practice'],['03','Interview Studio','Say it. Think it through. Try again.','A Gemini interviewer asks one question at a time for your chosen role. Answer by text or push-to-talk and ask for a practice summary.','#/studio','Enter the Studio']].map(([n,kind,title,desc,href,cta])=>`<article><div class="workflow-feature-label"><span>${n}</span>${kind}</div><h3>${title}</h3><p>${desc}</p><a class="workflow-text-link" href="${href}">${cta} ↗</a></article>`).join('')}</div></section><section class="workflow-difference"><div><span class="workflow-eyebrow">UNDERSTAND YOUR PROGRESS</span><h2>More than a<br>completed checkbox.</h2><p>Your track keeps learning, correctness and independent performance visible. The next recommendation follows the evidence you have recorded.</p><a class="workflow-text-link" href="#/progress">See how readiness works →</a></div><div>${[['Clear contracts','Know the inputs, ordering, precision and invalid-input rules before coding.'],['Support that steps back','Reveal one hint at a time. Open a worked answer only when you choose.'],['Recoverable work','Keep browser drafts, saved code revisions and distinct infrastructure errors.'],['Honest coverage','See which languages have automated checks and which tracks need more content.']].map(([t,d])=>`<article><span aria-hidden="true">✓</span><div><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></section><section class="workflow-section"><div class="workflow-section-heading"><span class="workflow-eyebrow">BRING YOUR CONTEXT</span><h2>A goal that looks like yours.</h2><p>Start with your target role, business domain, language and company. Adjust them as your plans change.</p></div><div class="workflow-domain-grid">${domains.map((d,i)=>`<a href="#/learn?setup=1&domain=${encodeURIComponent(d)}"><span>0${i+1} ↗</span><strong>${esc(d)}</strong><small>${d==='Investment Banking'?'Assessed Java exercises + role preparation':'Domain study material · coding coverage varies'}</small></a>`).join('')}</div><p class="workflow-coverage">Full automated assessment currently focuses on banking Java. Python, JavaScript and TypeScript retain manual coding practice. AI features require a connected Gemini service and an available pilot allowance.</p></section><section class="workflow-bottom"><span class="workflow-eyebrow">MAKE THE NEXT SESSION COUNT</span><h2>Your goal. A clear track.<br>One useful step today.</h2><a class="button primary large" href="#/learn?setup=1">Build my preparation track ↗</a></section></div>`;}
  function onboarding(){const old=profile(),p=model.profile({...old,domain:domains.includes(route().query.get('domain'))?route().query.get('domain'):old?.domain});return `<div class="workflow-onboarding"><a class="workflow-text-link" href="${old?'#/learn':'#/'}">← ${old?'Back to my track':'Back to overview'}</a><header><span class="workflow-eyebrow">LET’S START WITH YOUR GOAL</span><h1>What are you<br>preparing for?</h1><p>Four details give your preparation a direction. We’ll connect the learning, coding and interview practice that is available for your goal.</p></header><form id="workflow-profile"><div class="workflow-profile-grid"><label><span>01 · Target role</span><strong>Which role are you aiming for?</strong><select name="role">${roleConfig.map(r=>`<option value="${r.id}" ${r.id===p.role?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label><span>02 · Business domain</span><strong>Where will you apply your skills?</strong><select name="domain">${domains.map(d=>`<option ${d===p.domain?'selected':''}>${esc(d)}</option>`).join('')}</select></label><label><span>03 · Programming language</span><strong>What will you code in?</strong><select name="language">${Object.entries(languageConfig).map(([id,l])=>`<option value="${id}" ${id===p.language?'selected':''}>${l.name}${id==='java'?' · automated assessment':' · manual practice'}</option>`).join('')}</select></label><label><span>04 · Target company</span><strong>Where would you like to interview?</strong><input name="company" maxlength="120" value="${esc(p.company)}" placeholder="For example, SMBC · optional"><small>A preparation preference; these are representative questions.</small></label></div><div class="workflow-profile-extras"><label>Starting point<select name="level">${Object.entries(model.levels).map(([id,l])=>`<option value="${id}" ${id===p.level?'selected':''}>${l.name}</option>`).join('')}</select></label><label>Time per study session<select name="minutes">${[20,40,60].map(m=>`<option value="${m}" ${m===p.minutes?'selected':''}>${m} minutes</option>`).join('')}</select></label></div><div class="workflow-profile-submit"><p>Your track is saved in this browser. Changing your goal preserves your code drafts and learning records. AI personalisation is optional and asks for consent separately.</p><button class="button primary large" type="submit">${old?'Update my track':'Create my preparation track'} ↗</button></div><p class="workflow-form-status" role="status"></p></form><aside class="workflow-onboarding-note"><strong>A useful track starts with honest coverage.</strong><p>Banking Java has automated checks. Other domains include study and discussion material; they may have no dedicated coding exercises. The Java tutorial is available in Java. Other languages link to their official learning documentation.</p></aside></div>`;}
  function studioLink(p,round='technical',focus=''){return '#/studio?'+new URLSearchParams({role:p.role,domain:p.domain,language:p.language,company:p.company,round,...(focus?{focus}:{})});}
  function candidates(p){const tasks=window.PrepJourney.stages(p).flatMap(stage=>stage.tasks),remaining=tasks.filter(task=>!model.taskStatus(task,p,window.PrepJourney.evidence()).done);return (remaining.length?remaining:tasks).slice(0,32);}
  function recommendations(p){const plan=state.workflowAI?.[key(p)];if(!plan)return '';const tasks=new Map(candidates(p).map(t=>[t.id,t]));return `<section class="workflow-ai-result"><span class="workflow-eyebrow">GEMINI · OPTIONAL SUGGESTIONS</span><h2>A focus for your next sessions.</h2><p>${esc(plan.summary)}</p><ol>${plan.priorities.filter(row=>tasks.has(row.id)).map(row=>`<li><a href="${window.PrepJourney.taskHref(tasks.get(row.id),p)}">${esc(tasks.get(row.id).title)} ↗</a><p>${esc(row.reason)}</p></li>`).join('')}</ol><small>Generated ${esc(new Date(plan.generatedAt).toLocaleDateString())} · AI suggestions may be mistaken. Your evidence score is calculated separately.</small></section>`;}
  function track(){const p=profile();if(!p||route().query.get('setup')==='1')return onboarding();if(route().query.has('stage'))return window.PrepJourney.path();const result=window.PrepJourney.snapshot(p),role=roleConfig.find(r=>r.id===p.role),path=window.PrepJourney.stages(p),next=model.recommend(path,p,window.PrepJourney.evidence()),available=(window.PILOT_CATALOGUE||[]).filter(i=>i.domain===p.domain&&p.language==='java'),manual=p.language!=='java',languageDocs={python:'https://docs.python.org/3/tutorial/',javascript:'https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide',typescript:'https://www.typescriptlang.org/docs/handbook/intro.html'};return `<div class="workflow-track"><header class="workflow-track-heading"><div><span class="workflow-eyebrow">YOUR GOAL, CONNECTED TO YOUR NEXT STEP</span><h1>My preparation track</h1><p>${esc(role.name)}${p.company?' at '+esc(p.company):''}</p><div class="workflow-context"><span>${esc(p.domain)}</span><span>${languageConfig[p.language].name}</span><span>${p.minutes} min / session</span><span>${model.levels[p.level].name}</span></div></div><a class="button" href="#/learn?setup=1">Edit my goal</a></header><div class="workflow-track-grid"><div><section class="workflow-next"><span class="workflow-eyebrow">YOUR NEXT USEFUL STEP</span><h2>${esc(next?.task.title||'Rehearse the complete interview')}</h2><p>${esc(next?.stage.description||'Connect your knowledge and explain your decisions in a full mock.')}</p><a class="button primary" href="${next?window.PrepJourney.taskHref(next.task,p):studioLink(p)}">${next?.task.kind==='coding'?'Open coding exercise':next?.task.kind==='concept'?'Start learning':'Start rehearsal'} →</a><small>Selected from unfinished work for your starting point. Earlier gaps remain visible.</small></section><section class="workflow-track-stages"><div class="workflow-section-title"><h2>Your learning sequence</h2><span>${result.done} / ${result.total} recorded</span></div>${path.map((stage,i)=>{const s=result.milestones.find(x=>x.id===stage.id);return `<article data-complete="${s?.complete}"><span class="workflow-stage-number">${s?.complete?'✓':String(i+1).padStart(2,'0')}</span><div><small>${stage.label} · ${s?.done||0}/${s?.total||stage.tasks.length} steps</small><h3><a href="#/learn?stage=${stage.id}">${esc(stage.name)}</a></h3><p>${esc(stage.description)}</p><progress value="${s?.done||0}" max="${s?.total||1}" aria-label="${esc(stage.short)} progress"></progress></div><a href="#/learn?stage=${stage.id}" class="workflow-stage-link" aria-label="Open ${esc(stage.name)}">↗</a></article>`;}).join('')}</section><section class="workflow-study-resources"><span class="workflow-eyebrow">YOUR PRACTICE TOOLKIT</span><div><article><span>01 · LEARN</span><h3>${p.language==='java'?'Java data structures':'Official language foundations'}</h3><p>${p.language==='java'?'23 lessons with verified Java 17 examples, recall checks and interview explanations.':'A reviewed PrepSpace tutorial is not yet available in this language. Use the official documentation alongside manual practice.'}</p><a class="workflow-text-link" href="${p.language==='java'?'#/learning?language=java':languageDocs[p.language]}" ${p.language==='java'?'':'target="_blank" rel="noopener noreferrer"'}>Open learning material ↗</a></article><article><span>02 · LIVE CODING</span><h3>${available.length?available.length+' assessed Java exercises':'Practice coverage'}</h3><p>${available.length?'Implementation, debugging, test design and multi-file banking projects. Hints and answers stay under your control.':manual?'This language uses manual execution. Inspect output and add your own tests; Java grades do not carry across.':'No assessed exercises are tagged for this domain yet. Banking exercises are available as transferable practice.'}</p><a class="workflow-text-link" href="#/lab?${new URLSearchParams({round:'coding',domain:p.domain,language:p.language})}">Open Practice ↗</a>${!available.length?'<a class="workflow-text-link" href="#/lab?round=coding&domain=Investment+Banking&language='+p.language+'">Explore banking practice ↗</a>':''}</article></div></section>${recommendations(p)}<section class="workflow-ai-coach"><div><span class="workflow-eyebrow">OPTIONAL · AI PRIORITIES</span><h2>Get another perspective on your track.</h2><p>Gemini can suggest priorities from this track’s actual resources using your goal. It cannot change grades or mark your preparation complete.</p></div><form id="workflow-ai-form"><label><input type="checkbox" name="consent" required> Send my role, domain, language, company preference and resource list to Google Gemini for suggestions.</label><button class="button" ${aiBusy?'disabled':''}>${aiBusy?'Preparing suggestions…':'Suggest my priorities'}</button><small>Up to two suggestions per seven days; shared service capacity applies. Core preparation works without AI.</small><p role="status">${esc(aiError)}</p></form></section></div><aside>${scorePanel(p,result,true)}<section class="workflow-studio-card"><span class="workflow-eyebrow">INTERVIEW STUDIO</span><span class="workflow-studio-orb" aria-hidden="true">◉</span><h2>Practise the conversation.</h2><p>Your AI interviewer asks. You answer by text or voice. Then explore the follow-up.</p><a class="button primary" href="${studioLink(p)}">Meet my AI interviewer ↗</a><small>${service?.enabled?'Gemini connected · pilot allowance applies':'Gemini connection checked in the Studio'}</small></section><section class="workflow-rounds"><h3>Rehearse every round</h3>${roundConfig.map((round,i)=>`<a href="${studioLink(p,round.id)}"><span>0${i+1}</span>${esc(round.name)} ↗</a>`).join('')}<p>Company preferences guide representative practice. These are not verified employer questions.</p></section><a class="button" href="#/progress">View my visual roadmap ↗</a></aside></div></div>`;}
  function progressView(){const p=profile();return (p?`<div class="workflow-progress-score">${scorePanel(p,window.PrepJourney.snapshot(p))}</div>`:'')+window.PrepJourney.progressView();}
  async function mount(){if(!['home','learn','progress'].includes(route().path))return;await window.PrepPilotUI.ensureWorkspace();if(serviceWorkspace===state.pilotWorkspaceKey||serviceLoading)return;serviceLoading=true;const workspace=state.pilotWorkspaceKey;try{const r=await fetch('/api/studio/status',{cache:'no-store'});if(r.ok&&state.pilotWorkspaceKey===workspace){service=await r.json();serviceWorkspace=workspace;}}catch{}finally{serviceLoading=false;}}
  document.addEventListener('submit',async event=>{
    if(event.target.id==='workflow-profile'){
      event.preventDefault();await window.PrepPilotUI.ensureWorkspace();if(!window.PrepPilotUI.workspaceReady()){event.target.querySelector('[role=status]').textContent='Your workspace is unavailable. Refresh the connection before saving your goal.';return;}
      const p=model.profile(Object.fromEntries(new FormData(event.target)));state.learningJourney={...p,createdAt:state.learningJourney?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};state.studioSetup={...(state.studioSetup||{}),role:p.role,domain:p.domain,language:p.language,company:p.company};state.language=p.language;currentLanguage=p.language;if(['java','python'].includes(p.language))state.conceptLanguage=p.language;state.domain=p.domain;currentDomain=p.domain;state.role=p.role;currentRole=p.role;refreshLanguageContent();persist();aiError='';aiEpoch++;go('learn');render();
    }
    if(event.target.id==='workflow-ai-form'){
      event.preventDefault();if(aiBusy||!profile())return;const p=profile(),workspace=state.pilotWorkspaceKey,epoch=++aiEpoch,profileKey=key(p),ids=candidates(p).map(t=>t.id);if(!ids.length){aiError='This track needs more available resources before AI can suggest priorities.';render();return;}aiBusy=true;aiError='';render();
      try{const response=await fetch('/api/studio/plan',{method:'POST',headers:{'Content-Type':'application/json','X-PrepSpace-Workspace':workspace},body:JSON.stringify({...p,level:{beginner:'intermediate',intermediate:'intermediate',advanced:'senior'}[p.level],consent:true,requestId:crypto.randomUUID(),taskIds:ids})});const value=await response.json();if(!response.ok)throw new Error(value.error||'The service is unavailable.');if(epoch===aiEpoch&&workspace===state.pilotWorkspaceKey&&profile()&&key(profile())===profileKey){state.workflowAI??={};state.workflowAI[profileKey]=value;persist();}}
      catch(error){if(epoch===aiEpoch&&workspace===state.pilotWorkspaceKey)aiError=error.message||'AI suggestions are unavailable. Your track remains available.';}
      finally{aiBusy=false;if(route().path==='learn')render();}
    }
  });
  return {home,track,onboarding,score,scorePanel,mount,views:{home,learn:track,track,progress:progressView}};
})();
